static void Admit(LBXLicenseInstallationEstablishment *proof,BOOL first){SignedStatus=@"active";[proof.vault testUsePublicKey:TestLicensePublicDER() keyID:TestLicenseKeyID()];
    [proof.licenseOwner testUseProtocol:PreparedProtocol.class publicKey:TestLicensePublicDER() keyID:TestLicenseKeyID()];Check([Send(proof.licenseOwner,first?@"activate":@"validate")[@"result"] isEqual:@"active"],@"synthetic signed website admission");}
static LBXContainerRootPendingStore *Pending(LBXLicenseInstallationEstablishment *proof,NSString *path,BOOL create){__block LBXContainerRootPendingStore *pending=nil;double deadline=LBXLicenseIPCClock()+3;
    BOOL okay=[proof.licenseOwner performSourceOperation:^BOOL(NSError **error){pending=[LBXContainerRootPendingStore openDirectory:path licenseOwner:proof.licenseOwner configurationStore:proof.configurationStore preparedInstallation:proof create:create beforeDeadline:deadline error:error];return pending!=nil;} beforeDeadline:deadline error:nil];return okay?pending:nil;}
static NSDictionary *Request(NSString *operation,NSDictionary *arguments){NSMutableDictionary *r=[@{@"version":@1,@"family":@"container-mutation",@"operation":operation,@"requestID":NSUUID.UUID.UUIDString.lowercaseString,@"deadline":@(LBXLicenseIPCClock()+3)} mutableCopy];[r addEntriesFromDictionary:arguments];return r;}
static NSDictionary *Call(LBXContainerRootMutationOwner *owner,NSString *operation,NSDictionary *arguments){NSDictionary *request=Request(operation,arguments);dispatch_semaphore_t done=dispatch_semaphore_create(0);__block NSDictionary *reply=nil;
    [owner handleRequest:request completion:^(NSDictionary *value){reply=value;dispatch_semaphore_signal(done);}];Check(!dispatch_semaphore_wait(done,dispatch_time(DISPATCH_TIME_NOW,5*NSEC_PER_SEC)),@"bounded typed root owner completion");Check(LBXContainerMutationIPCValidateReply(reply,request,LBXLicenseIPCClock()),@"strict typed root reply");return reply;}
static BOOL Establish(LBXContainerRootMutationOwner *owner,double deadline){dispatch_semaphore_t done=dispatch_semaphore_create(0);__block BOOL ready=NO;
    [owner establishPreparedPendingBeforeDeadline:deadline completion:^(BOOL value){ready=value;dispatch_semaphore_signal(done);}];Check(!dispatch_semaphore_wait(done,dispatch_time(DISPATCH_TIME_NOW,5*NSEC_PER_SEC)),@"trusted setup queue bounded completion");return ready;}
static NSDictionary *Token(NSDictionary *slot){return @{@"token":slot[@"token"],@"epoch":slot[@"epoch"]};}
static void SuccessfulFlow(NSString *base,NSData *client){NSDictionary *paths=Paths(base,@"flow");LBXLicenseInstallationEstablishment *proof=Prepare(paths,client);Check(proof!=nil,@"actual pristine unpaired proof");LBXContainerRootMutationOwner *owner=[[LBXContainerRootMutationOwner alloc] initWithPreparedInstallation:proof pendingDirectory:paths[@"pending"]];Check(owner!=nil,@"typed production-style root assembly");NSDictionary *before=Snapshot(base);
    Check(!Establish(owner,LBXLicenseIPCClock()+3)&&[before isEqual:Snapshot(base)],@"unpaired preparation cannot create pending state");Check(![LBXContainerRootPendingStore openDirectory:paths[@"pending"] licenseOwner:proof.licenseOwner configurationStore:proof.configurationStore preparedInstallation:(LBXLicenseInstallationEstablishment *)[NSNull null] create:YES beforeDeadline:LBXLicenseIPCClock()+3 error:nil],@"nil typed proof cannot initialize");
    [proof.vault testUsePublicKey:TestLicensePublicDER() keyID:TestLicenseKeyID()];[proof.licenseOwner testUseProtocol:PreparedProtocol.class publicKey:TestLicensePublicDER() keyID:TestLicenseKeyID()];SignedStatus=@"active";
    NSDictionary *request=LBXLicenseIPCRequest(@"activate",@"AAAA-BBBB-CCCC-DDDD");dispatch_semaphore_t done=dispatch_semaphore_create(0);__block BOOL ready=NO;
    [proof.licenseOwner handleRequest:request completion:^(NSDictionary *reply){Check([reply[@"result"] isEqual:@"active"],@"source owner genuinely active completion");[owner establishPreparedPendingBeforeDeadline:[request[@"deadline"] doubleValue] completion:^(BOOL value){ready=value;dispatch_semaphore_signal(done);}];}];
    Check(!dispatch_semaphore_wait(done,dispatch_time(DISPATCH_TIME_NOW,5*NSEC_PER_SEC))&&ready,@"owner completion moves off source queue and preserves original deadline without deadlock");
    NSDictionary *status=Call(owner,@"status",@{});Check([status[@"result"] isEqual:@"status"]&&[status[@"state"][@"epoch"] isEqual:@"1"]&&status[@"state"][@"pending"]==NSNull.null,@"fresh established verified empty state");
    NSString *statePath=Join(paths[@"pending"],@"state.json");NSDictionary *privateState=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:statePath] options:0 error:nil];
    Check([privateState[@"context"] count]==3&&[privateState[@"context"][@"prepared"] isEqual:[proof privatePreparedWitness:nil]],@"full prepared private witness is durably bound alongside pairing and namespace");
    Check([status[@"state"] count]==3&&!status[@"state"][@"context"]&&!status[@"state"][@"marker"],@"public metadata projection exports no provenance/pairing/physical witnesses");
    before=Snapshot(base);Check(Establish(owner,LBXLicenseIPCClock()+3)&&[before isEqual:Snapshot(base)],@"complete repeated establishment is read-only reconciliation");
    NSDictionary *args=@{@"expectedEmptyEpoch":@"1",@"stageRequestID":NSUUID.UUID.UUIDString.lowercaseString,@"choices":@{@"name":@"Prepared saved setup",@"applications":@[@"com.burbn.instagram"],@"manualIdentifiers":NSNull.null,@"proxyReference":@""}};
    NSDictionary *staged=Call(owner,@"stage-create",args),*slot=staged[@"state"][@"pending"];Check([staged[@"result"] isEqual:@"staged"],@"typed creation stages exact saved setup");NSDictionary *saved=Call(owner,@"execute",Token(slot));Check([saved[@"result"] isEqual:@"saved"]&&saved[@"state"][@"pending"]==NSNull.null,@"exact saved document proof clears pending under held configuration lock");
    LBXContainerConfiguration *record=[LBXContainerConfiguration fromDictionary:saved[@"configuration"] error:nil],*edit=[record configurationByUpdatingName:@"Edited prepared setup" applications:@[@"com.burbn.instagram",@"com.facebook.Facebook"] manualIdentifiers:nil proxyReference:nil error:nil];
    status=Call(owner,@"status",@{});staged=Call(owner,@"stage-update",@{@"expectedEmptyEpoch":status[@"state"][@"epoch"],@"stageRequestID":NSUUID.UUID.UUIDString.lowercaseString,@"configuration":edit.privateDictionary,@"expected":record.privateDictionary});slot=staged[@"state"][@"pending"];Check([staged[@"result"] isEqual:@"staged"],@"exact-record proof stage supports guarded prepared witness without recursive lock");saved=Call(owner,@"execute",Token(slot));Check([saved[@"result"] isEqual:@"saved"]&&[saved[@"configuration"] isEqual:edit.privateDictionary],@"actual guarded same-file edit completes");
    before=Snapshot(base);Check(Establish(owner,LBXLicenseIPCClock()+3)&&[before isEqual:Snapshot(base)],@"already-established nonempty namespace reconciles rather than requiring or resetting empty records");
    LBXLicenseInstallationEstablishment *reopened=Open(paths,client);Check(reopened!=nil,@"same immutable prepared proof reopens");Admit(reopened,NO);LBXContainerRootMutationOwner *restart=[[LBXContainerRootMutationOwner alloc] initWithPreparedInstallation:reopened pendingDirectory:paths[@"pending"]];before=Snapshot(base);Check(Establish(restart,LBXLicenseIPCClock()+3)&&[before isEqual:Snapshot(base)],@"source owner restart preserves paired pending context and metadata bytes");Check([Call(restart,@"read",@{@"identifier":record.identifier})[@"configuration"] isEqual:edit.privateDictionary],@"reopened typed read returns exact full record");
    SignedStatus=@"revoked";Check([Send(reopened.licenseOwner,@"validate")[@"result"] isEqual:@"revoked"],@"fresh signed denial");before=Snapshot(base);Check(!Establish(restart,LBXLicenseIPCClock()+3)&&[before isEqual:Snapshot(base)],@"revocation permits no establishment/reconciliation effects");Check(Call(restart,@"status",@{})[@"state"]==NSNull.null,@"revoked context never projects cached readiness");Admit(reopened,NO);
    NSString *prepared=Join(paths[@"anchor"],@"prepared.json"),*held=Join(base,@"flow-held-proof");NSData *bytes=[NSData dataWithContentsOfFile:prepared];Check(!rename(prepared.fileSystemRepresentation,held.fileSystemRepresentation)&&Put(prepared,bytes,0600),@"same-byte prepared anchor independent replacement");before=Snapshot(base);Check(!Establish(restart,LBXLicenseIPCClock()+3)&&[before isEqual:Snapshot(base)],@"cached established pending rejects same-byte proof replacement and preserves exact state");Check(!Open(paths,client),@"restart cannot adopt replacement anchor");
}
static void RefusalTests(NSString *base,NSData *client){for(NSString *kind in @[@"wrong-path",@"nonempty",@"old-context",@"partial"]){NSDictionary *paths=Paths(base,kind);LBXLicenseInstallationEstablishment *proof=Prepare(paths,client);Check(proof!=nil,@"fresh bounded refusal fixture");Admit(proof,YES);NSString *path=paths[@"pending"];
    if([kind isEqual:@"wrong-path"])path=[path stringByAppendingString:@"-caller"];
    if([kind isEqual:@"nonempty"]){LBXContainerConfiguration *record=[LBXContainerConfiguration createWithName:@"Preexisting saved record" applications:@[@"com.burbn.instagram"] manualIdentifiers:nil proxyReference:@"" error:nil];Check([proof.configurationStore commitConfiguration:record replacing:nil beforeDeadline:LBXLicenseIPCClock()+3 error:nil],@"actual preexisting configuration fixture");}
    if([kind isEqual:@"partial"])Check(!mkdir(path.fileSystemRepresentation,0700),@"unknown pending-only directory fixture");
    if([kind isEqual:@"old-context"]){double deadline=LBXLicenseIPCClock()+3;Check([proof.licenseOwner performSourceOperation:^BOOL(NSError **error){return [LBXContainerRootPendingStore openDirectory:path licenseOwner:proof.licenseOwner configurationStore:proof.configurationStore create:YES beforeDeadline:deadline error:error]!=nil;} beforeDeadline:deadline error:nil],@"earlier already-paired context fixture has no prepared witness");}
    NSDictionary *before=Snapshot(base);Check(!Pending(proof,path,YES)&&[before isEqual:Snapshot(base)],@"wrong path/nonempty/old context/partial state cannot be adopted or repaired");Admit(proof,NO);before=Snapshot(base);Check(!Pending(proof,path,YES)&&[before isEqual:Snapshot(base)],@"fresh signed retry preserves unknown state without silent reset");
}}
static void FreshNodeDriftTests(NSString *base,NSData *client){for(NSString *kind in @[@"root-mode",@"lock-replacement"]){NSDictionary *paths=Paths(base,kind);LBXLicenseInstallationEstablishment *proof=Prepare(paths,client);Check(proof!=nil,@"fresh node-drift preparation");Admit(proof,YES);NSString *lock=Join(paths[@"pending"],@"pending.lock"),*marker=Join(base,[NSString stringWithFormat:@".%@.socialbox-root-pending-v1.json",[paths[@"pending"] lastPathComponent]]);__block BOOL changed=NO;
    [LBXLicenseInstallationEstablishment testBoundaryHandler:^(NSString *boundary){if(changed||![boundary isEqual:@"before_final_reobservation"])return;
        if([kind isEqual:@"root-mode"]&&Snapshot(paths[@"pending"])){changed=YES;Check(!chmod([paths[@"pending"] fileSystemRepresentation],0755),@"created pending root actually becomes public during proof observation");}
        if([kind isEqual:@"lock-replacement"]&&Snapshot(lock)){changed=YES;Check(!rename(lock.fileSystemRepresentation,[Join(base,@"held-independent-new-lock") fileSystemRepresentation])&&Put(lock,NSData.data,0600),@"created pending lock actually replaced during proof observation");}
    }];Check(!Pending(proof,paths[@"pending"],YES)&&changed&&!Snapshot(marker)&&!Snapshot(Join(paths[@"pending"],@"state.json")),@"known root/lock drift stops later marker/state effects while preserving partial nodes");[LBXLicenseInstallationEstablishment testBoundaryHandler:nil];}}
static void CompleteLossTest(NSString *base,NSData *client){NSDictionary *paths=Paths(base,@"complete-loss");LBXLicenseInstallationEstablishment *proof=Prepare(paths,client);Check(proof!=nil,@"fresh complete-loss fixture");Admit(proof,YES);LBXContainerRootMutationOwner *owner=[[LBXContainerRootMutationOwner alloc] initWithPreparedInstallation:proof pendingDirectory:paths[@"pending"]];Check(Establish(owner,LBXLicenseIPCClock()+3),@"real first paired pending establishment");NSDictionary *staged=Call(owner,@"stage-create",@{@"expectedEmptyEpoch":@"1",@"stageRequestID":NSUUID.UUID.UUIDString.lowercaseString,@"choices":@{@"name":@"Unpublished exact candidate survives loss refusal",@"applications":@[@"com.burbn.instagram"],@"manualIdentifiers":NSNull.null,@"proxyReference":@""}});Check([staged[@"result"] isEqual:@"staged"],@"actual staged candidate with otherwise empty configuration namespace");NSString *marker=Join(base,[NSString stringWithFormat:@".%@.socialbox-root-pending-v1.json",[paths[@"pending"] lastPathComponent]]);Check(!rename([paths[@"pending"] fileSystemRepresentation],[Join(base,@"held-lost-pending") fileSystemRepresentation])&&!rename(marker.fileSystemRepresentation,[Join(base,@"held-lost-marker") fileSystemRepresentation]),@"both replaceable pending leaves absent; exact candidate retained in held test nodes");LBXLicenseInstallationEstablishment *reopened=Open(paths,client);Check(reopened!=nil,@"immutable preparation and consumed record reopen independently of missing pending leaves");Admit(reopened,NO);NSDictionary *before=Snapshot(base);LBXContainerRootMutationOwner *restart=[[LBXContainerRootMutationOwner alloc] initWithPreparedInstallation:reopened pendingDirectory:paths[@"pending"]];Check(!Establish(restart,LBXLicenseIPCClock()+3)&&[before isEqual:Snapshot(base)]&&!Snapshot(paths[@"pending"])&&!Snapshot(marker),@"consumed attempt survives restart and refuses reinitializing epoch1 after complete pending loss");Admit(reopened,NO);before=Snapshot(base);Check(!Establish(restart,LBXLicenseIPCClock()+3)&&[before isEqual:Snapshot(base)],@"fresh validation cannot remint pending after complete loss");}
static void PendingInterruptionTests(NSString *base,NSData *client){for(NSString *boundary in @[@"before_pending_mkdir",@"pending_directory_created",@"pending_lock_created",@"pending_marker_synced",@"pending_state_synced",@"pending_established"]){NSDictionary *paths=Paths(base,boundary);LBXLicenseInstallationEstablishment *proof=Prepare(paths,client);Check(proof!=nil,@"fresh interruption preparation");Admit(proof,YES);[LBXContainerRootPendingStore testStopEstablishmentAfterBoundary:boundary];Check(!Pending(proof,paths[@"pending"],YES),@"failure-only establishment seam never reports success");[LBXContainerRootPendingStore testStopEstablishmentAfterBoundary:nil];Admit(proof,NO);NSDictionary *before=Snapshot(base);BOOL recoverable=[@[@"pending_state_synced",@"pending_established"] containsObject:boundary];LBXContainerRootPendingStore *retry=Pending(proof,paths[@"pending"],YES);Check((retry!=nil)==recoverable,@"only complete published state reconciles; consumed attempt or partial stays closed");Check([before isEqual:Snapshot(base)],@"partial refusal or complete reconciliation preserves all existing bytes and inodes");}}
int main(void){@autoreleasepool{char p[]="/private/tmp/socialbox-paired-pending.XXXXXX";Check(mkdtemp(p)!=NULL,@"actual temporary root fixture");NSString *base=[NSString stringWithUTF8String:p];Check(!chown(base.fileSystemRepresentation,geteuid(),getegid()),@"fixed fixture group");NSData *client=[@"#!/fixture-client\n" dataUsingEncoding:NSUTF8StringEncoding];for(NSString *name in @[@"installer",@"service",@"client"])Check(Put(Join(base,name),[[NSString stringWithFormat:@"#!/fixture-%@\n",name] dataUsingEncoding:NSUTF8StringEncoding],0755),@"actual pinned executable fixtures");SuccessfulFlow(base,client);RefusalTests(base,client);FreshNodeDriftTests(base,client);CompleteLossTest(base,client);PendingInterruptionTests(base,client);[NSFileManager.defaultManager removeItemAtPath:base error:nil];printf("%s: %lu paired pending establishment assertions, %lu failures (actual files; synthetic signed admission)\n",failures?"FAIL":"PASS",(unsigned long)checks,(unsigned long)failures);return failures?1:0;}}
